import sys
import openpyxl

def is_whole_number(v):
    if isinstance(v, bool):
        return False
    try:
        return float(v).is_integer()
    except (TypeError, ValueError):
        return False

def main():
    src, dst = sys.argv[1], sys.argv[2]
    wb = openpyxl.load_workbook(src)
    ws = wb['Sheet1']

    for row in range(1, 16):  # F1:J15 -> rows 1..15
        f_val = ws.cell(row=row, column=6).value
        j_val = ws.cell(row=row, column=10).value
        if f_val == 'Marble Slab Creamery' and is_whole_number(j_val):
            ws.cell(row=row, column=6).value = 'Georgia State WH'

    wb.save(dst)

if __name__ == '__main__':
    main()

