import sys
import openpyxl

def main():
    src_path, out_path = sys.argv[1], sys.argv[2]

    wb = openpyxl.load_workbook(src_path)

    # Identify sheets by normalizing names.
    def find_sheet(substr):
        for ws in wb.worksheets:
            if substr.lower() in ws.title.lower():
                return ws
        raise ValueError("Sheet not found: " + substr)

    main_ws = find_sheet("main unique id")
    get_ws = find_sheet("result what i am getting")

    # Read the unique id list from Main sheet (column A).
    main_ids = []
    for row in main_ws.iter_rows(min_col=1, max_col=1):
        v = row[0].value
        if v is not None:
            main_ids.append(v)

    # Read "getting" sheet into a dict keyed by unique id.
    header = [c.value for c in get_ws[1]]
    data_by_id = {}
    for row in get_ws.iter_rows(min_row=2, values_only=True):
        if row[0] is None:
            continue
        data_by_id[row[0]] = row  # full row including header position

    n_cols = len(header)

    # Build sorted result: main IDs sorted, fill with existing row or empty.
    sorted_ids = sorted(main_ids, key=lambda x: (isinstance(x, str), x))
    result_rows = []
    for uid in sorted_ids:
        if uid in data_by_id:
            result_rows.append(list(data_by_id[uid]))
        else:
            result_rows.append([uid] + [None] * (n_cols - 1))

    # Ensure header columns; the getting header is what we want.
    final_header = list(header)

    # Write to the 'MyResult' sheet (answer_position A1:O20).
    if "MyResult" in wb.sheetnames:
        del wb["MyResult"]
    out_ws = wb.create_sheet("MyResult")

    out_ws.append(final_header)
    for r in result_rows:
        out_ws.append(r)

    wb.save(out_path)
    print("Wrote", out_path)

if __name__ == "__main__":
    main()

import sys
import openpyxl

def main():
    input_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(input_path)
    ws = wb['Sheet1']

    # Determine the actual data range on Sheet1: from row 1 (header) to the
    # last row that has a value in column A (the data column A that the user
    # wants processed until its last row).
    last_data_row = 1
    for row in range(1, ws.max_row + 1):
        if ws.cell(row=row, column=1).value is not None:
            last_data_row = row

    # Column AG is column 33.
    COUNT_COL = 33
    NUM_COLS = 33  # A..AG

    # Collect header and data rows.
    header = [ws.cell(row=1, column=c).value for c in range(1, NUM_COLS + 1)]
    rows = []
    for r in range(2, last_data_row + 1):
        row_vals = [ws.cell(row=r, column=c).value for c in range(1, NUM_COLS + 1)]
        rows.append(row_vals)

    # Duplicate rows based on the count in column AG (column 33, index 32).
    expanded = []
    for row_vals in rows:
        count = row_vals[COUNT_COL - 1]
        if count is None or isinstance(count, (str,)) and not str(count).strip().lstrip('-').isdigit():
            count = 1
        else:
            try:
                count = int(count)
            except (TypeError, ValueError):
                count = 1
        if count < 1:
            count = 1
        for _ in range(count):
            expanded.append(list(row_vals))

    # Create Sheet2 at the beginning of the workbook.
    if 'Sheet2' in wb.sheetnames:
        del wb['Sheet2']
    ws2 = wb.create_sheet('Sheet2', 0)

    # Header row.
    for c, val in enumerate(header, start=1):
        ws2.cell(row=1, column=c, value=val)

    # Data rows.
    for i, row_vals in enumerate(expanded, start=2):
        for c, val in enumerate(row_vals, start=1):
            ws2.cell(row=i, column=c, value=val)

    wb.save(output_path)

if __name__ == '__main__':
    main()

import sys
import re
import openpyxl

def extract_collection(text):
    if not isinstance(text, str):
        return None
    # Find 'Collection-' and capture text up to first comma or end
    idx = text.find('Collection-')
    if idx == -1:
        return None
    start = idx + len('Collection-')
    end = text.find(',', start)
    if end == -1:
        end = len(text)
    return text[start:end].strip()

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Sheet1']

    # Fill B2:B7 based on column A extraction
    for row in range(2, 8):
        a_val = ws.cell(row=row, column=1).value
        ws.cell(row=row, column=2).value = extract_collection(a_val)

    wb.save(output_path)

if __name__ == '__main__':
    main()

