#!/usr/bin/env python3
import sys
import openpyxl
from openpyxl.utils import column_index_from_string


def compute_count(ws, row=26, start="L"):
    col_start = column_index_from_string(start)
    col_end = column_index_from_string("SHA")
    vals = []
    for c in range(col_start, col_end + 1):
        v = ws.cell(row=row, column=c).value
        if v is None:
            continue
        try:
            vals.append(float(v))
        except (TypeError, ValueError):
            continue
    if not vals:
        return 0
    ref = vals[0]
    count = 0
    i = 1
    n = len(vals)
    while i < n:
        if vals[i] >= ref * 1.1:
            count += 1
            if i + 1 < n:
                ref = vals[i + 1]
            i += 1
        else:
            i += 1
    return count


def main():
    src = sys.argv[1]
    dst = sys.argv[2]
    wb = openpyxl.load_workbook(src)
    ws = wb.active
    ws["B6"] = compute_count(ws)
    wb.save(dst)


if __name__ == "__main__":
    main()

