import sys
import datetime
import openpyxl

def main():
    src = sys.argv[1]
    dst = sys.argv[2]

    wb = openpyxl.load_workbook(src, data_only=False)
    ws = wb["Sheet1"]

    # Table 1: columns A (Student ID), C (Visit date), starting at row 2.
    # Delimit the Table1 rows: continue while col A has a student id.
    table1 = []  # list of (student_id, visit_date)
    r = 2
    while True:
        sid = ws.cell(row=r, column=1).value
        vdate = ws.cell(row=r, column=3).value
        if sid is None:
            break
        table1.append((sid, vdate))
        r += 1

    def resolve_date(v):
        if isinstance(v, datetime.datetime):
            return v.date()
        if isinstance(v, datetime.date):
            return v.date()
        # might be numeric excel serial
        if isinstance(v, (int, float)):
            return datetime.datetime(1899, 12, 30) + datetime.timedelta(days=v)
        return None

    # Answer target cell: J2 (student id in H2, submission date in I2).
    sid2 = ws.cell(row=2, column=8).value   # H2
    sub_date = resolve_date(ws.cell(row=2, column=9).value)  # I2

    sub_date_dt = datetime.datetime(sub_date.year, sub_date.month, sub_date.day)

    candidates = [v for (s, v) in table1
                  if s == sid2 and resolve_date(v) is not None and resolve_date(v) < sub_date]

    if candidates:
        ans = max(candidates)
        # write as a proper datetime at midnight
        answer_dt = datetime.datetime(ans.year, ans.month, ans.day)
    else:
        answer_dt = None

    # Only modify the answer_position cell J2.
    if answer_dt is not None:
        ws.cell(row=2, column=10).value = answer_dt
        ws.cell(row=2, column=10).number_format = "YYYY-MM-DD"
    else:
        ws.cell(row=2, column=10).value = None

    wb.save(dst)

if __name__ == "__main__":
    main()
